/**
 * Check if API key exists in environment
 */
export function checkApiKeyEnv(envVar: string): { configured: boolean; value?: string } {
  const value = process.env[envVar];
  if (value && value.trim() !== '') {
    return { configured: true, value: value.trim() };
  }
  return { configured: false };
}

/**
 * Check if API key is stored in database
 */
export function checkApiKeyInDb(platform: string): { configured: boolean; keyId?: number; maskedKey?: string } {
  try {
    const db = getDb();
    const row = db.prepare('SELECT id, encrypted_key, iv, auth_tag FROM api_keys WHERE platform = ? AND enabled = 1 LIMIT 1').get(platform) as { id: number; encrypted_key: string; iv: string; auth_tag: string } | undefined;
    if (row) {
      return { configured: true, keyId: row.id };
    }
  } catch {
    // Ignore DB errors
  }
  return { configured: false };
}

/**
 * Get provider status from DSH settings
 */
export function getProviderStatusFromDSH(dshSettings: DSHSettings): ProviderStatus[] {
  const providers = dshSettings['llm-pi-ai']?.providers || {};
  const statuses: ProviderStatus[] = [];

  for (const [name, config] of Object.entries(providers)) {
    const displayInfo = getProviderDisplayInfo(name);
    const envCheck = checkApiKeyEnv(config.apiKeyEnv);
    const dbCheck = checkApiKeyInDb(name);

    const configured = envCheck.configured || dbCheck.configured;

    // Determine which tiers this provider serves
    const tiers: string[] = [];
    for (const model of config.models) {
      if (model.id.includes('s-tier') || model.id.includes('opus') || model.id.includes('kimi-k3') || model.id.includes('gemini-3.6')) {
        tiers.push('S-Tier');
      } else if (model.id.includes('a-tier') || model.id.includes('kimi-k2') || model.id.includes('qwen3') || model.id.includes('deepseek-v4') || model.id.includes('glm-5')) {
        tiers.push('A-Tier');
      } else {
        tiers.push('B-Tier');
      }
    }

    // Deduplicate tiers
    const uniqueTiers = [...new Set(tiers)];

    statuses.push({
      name,
      displayName: config.displayName || displayInfo.name,
      apiKeyEnv: config.apiKeyEnv,
      baseURL: config.baseURL,
      apiType: config.api,
      models: config.models,
      keyConfigured: configured,
      keyValue: envCheck.value,
      modelsCount: config.models.length,
      tiers: uniqueTiers,
    });
  }

  return statuses;
}

/**
 * Import DSH settings into JiMesh database
 */
export function importDSHSettings(dshSettings: DSHSettings, options: { dryRun?: boolean; overwrite?: boolean } = {}): ImportResult {
  const providers = dshSettings['llm-pi-ai']?.providers || {};
  const result: ImportResult = {
    success: true,
    imported: 0,
    skipped: 0,
    errors: [],
    providers: [],
  };

  const providerStatuses = getProviderStatusFromDSH(dshSettings);

  if (options.dryRun) {
    result.providers = providerStatuses;
    return result;
  }

  const db = getDb();

  for (const [name, config] of Object.entries(providers)) {
    const validationErrors = validateProviderConfig(config, name);
    if (validationErrors.length > 0) {
      result.errors.push(...validationErrors);
      result.success = false;
      continue;
    }

    const envCheck = checkApiKeyEnv(config.apiKeyEnv);
    const dbCheck = checkApiKeyInDb(name);

    if (!envCheck.configured && !dbCheck.configured) {
      result.errors.push(`Provider ${name}: API key not found in environment (${config.apiKeyEnv}) or database`);
      result.success = false;
      continue;
    }

    if (envCheck.configured && !dbCheck.configured) {
      // Import the key from environment
      try {
        const { encrypted, iv, authTag } = encrypt(envCheck.value!);

        // Check if key already exists
        const existing = db.prepare('SELECT id FROM api_keys WHERE platform = ? LIMIT 1').get(name);
        if (existing && !options.overwrite) {
          result.skipped++;
          continue;
        }

        if (existing && options.overwrite) {
          db.prepare(`
            UPDATE api_keys 
            SET encrypted_key = ?, iv = ?, auth_tag = ?, status = 'unknown', enabled = 1, updated_at = datetime('now')
            WHERE id = ?
          `).run(encrypted, iv, authTag, (existing as { id: number }).id);
        } else {
          db.prepare(`
            INSERT INTO api_keys (platform, label, encrypted_key, iv, auth_tag, status, enabled)
            VALUES (?, ?, ?, ?, ?, 'unknown', 1)
          `).run(name, config.displayName || name, encrypted, iv, authTag);
        }
        result.imported++;
      } catch (error) {
        result.errors.push(`Provider ${name}: ${(error as Error).message}`);
        result.success = false;
      }
    } else {
      result.skipped++;
    }
  }

  result.providers = providerStatuses;
  return result;
}

/**
 * Test provider connection
 */
export async function testProviderConnection(providerName: string, baseURL: string, apiKey?: string): Promise<{ success: boolean; latency?: number; error?: string }> {
  const start = Date.now();
  try {
    // Try to fetch models from the provider
    const url = `${baseURL.replace(/\/$/, '')}/models`;
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
    };
    if (apiKey) {
      headers['Authorization'] = `Bearer ${apiKey}`;
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 10000);

    const response = await fetch(url, {
      method: 'GET',
      headers,
      signal: controller.signal,
    });

    clearTimeout(timeout);

    if (response.ok) {
      return { success: true, latency: Date.now() - start };
    } else {
      return { success: false, latency: Date.now() - start, error: `HTTP ${response.status}: ${response.statusText}` };
    }
  } catch (error) {
    return { success: false, latency: Date.now() - start, error: (error as Error).message };
  }
}

/**
 * Get tier models from chain data
 */
export function getTierModels(tierId: string): any[] {
  try {
    const filePath = path.join(process.cwd(), 'data', 'chains', `${tierId}.json`);
    if (!fs.existsSync(filePath)) {
      return [];
    }
    const content = fs.readFileSync(filePath, 'utf-8');
    const data = JSON.parse(content);
    return data.models || [];
  } catch {
    return [];
  }
}

/**
 * Get all tier information
 */
export function getAllTiers(): { id: string; name: string; emoji: string; color: string; models: any[]; count: number }[] {
  const tiers = ['s-tier', 'a-tier', 'b-tier'];
  return tiers.map(id => {
    const models = getTierModels(id);
    const tierInfo: Record<string, { name: string; emoji: string; color: string }> = {
      's-tier': { name: 'S-Tier', emoji: '🏆', color: '#F59E0B' },
      'a-tier': { name: 'A-Tier', emoji: '⭐', color: '#3B82F6' },
      'b-tier': { name: 'B-Tier', emoji: '✨', color: '#8B5CF6' },
    };
    const info = tierInfo[id] || { name: id, emoji: '📦', color: '#6B7280' };
    return {
      id,
      name: info.name,
      emoji: info.emoji,
      color: info.color,
      models,
      count: models.length,
    };
  });
}"}

