import { Router } from 'express';
import type { Request, Response } from 'express';
import { z } from 'zod';
import multer from 'multer';
import { requireAuth } from '../middleware/requireAuth.js';
import {
  parseDSHSettings,
  importDSHSettings,
  getProviderStatusFromDSH,
  testProviderConnection,
  getAllTiers,
  getTierModels,
  getProviderSetupUrl,
  getProviderDisplayInfo,
} from '../services/dshImporter.js';

export const dshImportRouter = Router();

// Multer for file upload
const upload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: 1024 * 1024 }, // 1MB limit
  fileFilter: (_req, file, cb) => {
    if (file.mimetype === 'application/x-yaml' ||
        file.mimetype === 'text/yaml' ||
        file.originalname.endsWith('.yaml') ||
        file.originalname.endsWith('.yml')) {
      cb(null, true);
    } else {
      cb(new Error('Only YAML files are allowed'));
    }
  },
});

/**
 * POST /api/dsh/import - Import DSH YAML settings file
 */
dshImportRouter.post('/import', requireAuth, upload.single('file'), (req: Request, res: Response) => {
  try {
    if (!req.file) {
      res.status(400).json({ error: { message: 'No file uploaded' } });
      return;
    }

    const yamlContent = req.file.buffer.toString('utf-8');
    const dshSettings = parseDSHSettingsFromString(yamlContent);

    const overwrite = req.body.overwrite === 'true' || req.body.overwrite === true;
    const result = importDSHSettings(dshSettings, { overwrite });

    res.json({
      success: result.success,
      imported: result.imported,
      skipped: result.skipped,
      errors: result.errors,
      providers: result.providers,
    });
  } catch (error) {
    res.status(400).json({ error: { message: (error as Error).message } });
  }
});

/**
 * POST /api/dsh/test - Test provider connection
 */
const testConnectionSchema = z.object({
  providerName: z.string(),
  baseURL: z.string().url(),
  apiKey: z.string().optional(),
});

dshImportRouter.post('/test', requireAuth, async (req: Request, res: Response) => {
  const parsed = testConnectionSchema.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: { message: parsed.error.errors.map(e => e.message).join(', ') } });
    return;
  }

  const { providerName, baseURL, apiKey } = parsed.data;
  const result = await testProviderConnection(providerName, baseURL, apiKey);

  res.json(result);
});

/**
 * GET /api/dsh/settings - Get current DSH-compatible settings/status
 */
dshImportRouter.get('/settings', requireAuth, (_req: Request, res: Response) => {
  try {
    const tiers = getAllTiers();
    const providers = getConfiguredProviders();

    res.json({
      tiers: tiers.map(t => ({
        id: t.id,
        name: t.name,
        emoji: t.emoji,
        color: t.color,
        modelCount: t.count,
        models: t.models.map(m => ({
          priority: m.priority,
          platform: m.platform,
          modelId: m.model_id,
          displayName: m.display_name,
          intelligenceRank: m.intelligence_rank,
          supportsVision: m.supports_vision,
          supportsTools: m.supports_tools,
        })),
      })),
      providers: providers.map(p => ({
        name: p.name,
        displayName: p.displayName,
        emoji: p.emoji,
        color: p.color,
        apiKeyEnv: p.apiKeyEnv,
        baseURL: p.baseURL,
        apiType: p.apiType,
        keyConfigured: p.keyConfigured,
        modelsCount: p.modelsCount,
        tiers: p.tiers,
        setupUrl: p.setupUrl,
