 */
dshImportRouter.get('/tiers', requireAuth, (_req: Request, res: Response) => {
  try {
    const tiers = getAllTiers();
    res.json({
      tiers: tiers.map(t => ({
        id: t.id,
        name: t.name,
        emoji: t.emoji,
