 */
dshImportRouter.get('/tiers/:tierId', requireAuth, (req: Request, res: Response) => {
  try {
    const { tierId } = req.params;
    const models = getTierModels(tierId);

    const tierInfo: Record<string, { name: string; emoji: string; color: string }> = {
      's-tier': { name: 'S-Tier', emoji: '🏆', color: '#F59E0B' },
      'a-tier': { name: 'A-Tier', emoji: '⭐', color: '#3B82F6' },
      'b-tier': { name: 'B-Tier', emoji: '✨', color: '#8B5CF6' },
    };

    const info = tierInfo[tierId] || { name: tierId, emoji: '📦', color: '#6B7280' };

    res.json({
      id: tierId,
      name: info.name,
      emoji: info.emoji,
      color: info.color,
      modelCount: models.length,
      models,
    });
  } catch (error) {
    res.status(500).json({ error: { message: (error as Error).message } });
  }
});

/**
 * POST /api/dsh/preview - Preview DSH import without applying
 */
dshImportRouter.post('/preview', requireAuth, upload.single('file'), (req: Request, res: Response) => {
  try {
    if (!req.file) {
      res.status(400).json({ error: { message: 'No file uploaded' } });
      return;
    }

    const yamlContent = req.file.buffer.toString('utf-8');
    const dshSettings = parseDSHSettingsFromString(yamlContent);
    const result = importDSHSettings(dshSettings, { dryRun: true });

    res.json({
      success: result.success,
      providers: result.providers,
      errors: result.errors,
    });
  } catch (error) {
    res.status(400).json({ error: { message: (error as Error).message } });
  }
});

/**
 * Parse DSH settings from string (for preview/import without file)
 */
function parseDSHSettingsFromString(yamlContent: string): any {
  return yaml.parse(yamlContent);
}

/**
 * Get configured providers from database
 */
function getConfiguredProviders(): any[] {
  const db = require('../db/index.js').getDb();
  const keys = db.prepare('SELECT platform, label, status, enabled, base_url FROM api_keys WHERE enabled = 1').all() as any[];

  // Build provider list from both DB and environment
  const envProviders = [
    { name: 'lightning', env: 'LIGHTNING_API_KEY', baseURL: 'https://lightning.ai/api/v1/', api: 'openai-completions' },
    { name: 'bai', env: 'BAI_API_KEY', baseURL: 'https://api.b.ai/v1/', api: 'openai-completions' },
    { name: 's-tier', env: 'S_TIER_API_KEY', baseURL: 'http://localhost:3011/v1', api: 'openai-completions' },
  ];

  const configured: any[] = [];

  for (const envProv of envProviders) {
    const dbKey = keys.find(k => k.platform === envProv.name);
    const displayInfo = getProviderDisplayInfo(envProv.name);
    const hasKey = !!process.env[envProv.env] || !!dbKey;

    configured.push({
      name: envProv.name,
      displayName: dbKey?.label || displayInfo.name,
      emoji: displayInfo.emoji,
      color: displayInfo.color,
      apiKeyEnv: envProv.env,
      baseURL: dbKey?.base_url || envProv.baseURL,
      apiType: envProv.api,
      keyConfigured: hasKey,
      modelsCount: 0, // Will be populated from DSH settings
      tiers: [],
      setupUrl: getProviderSetupUrl(envProv.name),
    });
  }

  return configured;
