    if (file.mimetype === 'application/x-yaml' ||
        file.mimetype === 'text/yaml' ||
        file.originalname.endsWith('.yaml') ||
        file.originalname.endsWith('.yml')) {
      cb(null, true);
    } else {
      cb(new Error('Only YAML files are allowed'));
    }
  },
});

/**
 * POST /api/dsh/import - Import DSH YAML settings file
 */
dshImportRouter.post('/import', requireAuth, upload.single('file'), (req: Request, res: Response) => {
  try {
    if (!req.file) {
      res.status(400).json({ error: { message: 'No file uploaded' } });
      return;
    }

    const yamlContent = req.file.buffer.toString('utf-8');
    const dshSettings = parseDSHSettingsFromString(yamlContent);

    const overwrite = req.body.overwrite === 'true' || req.body.overwrite === true;
    const result = importDSHSettings(dshSettings, { overwrite });

    res.json({
      success: result.success,
      imported: result.imported,
      skipped: result.skipped,
      errors: result.errors,
      providers: result.providers,
    });
  } catch (error) {
    res.status(400).json({ error: { message: (error as Error).message } });
  }
});

