          </p>
        </div>
        <Button variant="ghost" size="icon" onClick={onDismiss}>
          ✕
        </Button>
      </div>
      {result.errors.length > 0 && (
        <div className="text-sm text-destructive">
          <ul className="list-disc list-inside space-y-1">
            {result.errors.map((e: string, i: number) => (
              <li key={i}>{e}</li>
            ))}
          </ul>
        </div>
      )}
    </div>
  )
}

function FileUploadArea({
  file,
  onChange,
  onImport,
  disabled,
}: {
  file: File | null
  onChange: (file: File | null) => void
  onImport: () => void
  disabled: boolean
}) {
  const [dragActive, setDragActive] = useState(false)

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true)
    } else if (e.type === 'dragleave') {
      setDragActive(false)
    }
  }

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setDragActive(false)
    if (e.dataTransfer.files.length > 0) {
      const f = e.dataTransfer.files[0]
      if (f.name.endsWith('.yaml') || f.name.endsWith('.yml')) {
        onChange(f)
      }
    }
  }

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files?.length) {
      onChange(e.target.files[0])
    }
  }

  if (file) {
    return (
      <div className="p-4 bg-muted/50 rounded-lg border">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className="text-2xl">📄</span>
            <div>
              <p className="font-medium">{file.name}</p>
              <p className="text-sm text-muted-foreground">
                {(file.size / 1024).toFixed(1)} KB
              </p>
            </div>
          </div>
          <div className="flex gap-2">
            <Button variant="outline" size="sm" onClick={() => onChange(null)}>
              Remove
            </Button>
            <Button onClick={onImport} disabled={disabled}>
              <Upload className="size-4 mr-1" />
              Import
            </Button>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div
      className={`p-8 text-center border-2 border-dashed rounded-lg transition-colors ${
        dragActive ? 'border-primary bg-primary/5' : 'border-muted'
      }`}
      onDragEnter={handleDrag}
      onDragLeave={handleDrag}
      onDragOver={handleDrag}
      onDrop={handleDrop}
    >
      <input
        type="file"
        accept=".yaml,.yml"
        onChange={handleFileSelect}
        className="hidden"
        id="dsh-file"
      />
      <label htmlFor="dsh-file" className="cursor-pointer">
        <Upload className="size-12 mx-auto text-muted-foreground mb-3" />
        <p className="text-lg font-medium mb-1">Drop your DSH settings.yaml here</p>
        <p className="text-sm text-muted-foreground">or click to browse</p>
      </label>
    </div>
  )
}","file_path":"/home/ji/projects/jimesh/client/src/pages/OnboardingPage.tsx"}

