                    </div>
                    <span className={`ml-2 text-xs font-medium ${
                      isCompleted || isCurrent ? 'text-foreground' : 'text-muted-foreground'
                    }`}>
                      {s.title}
                    </span>
                  </div>
                </React.Fragment>
              )
            })}
          </div>
        </div>
      </div>

      {/* Content */}
      <main className="mx-auto max-w-6xl px-6 py-8">
        {/* Step Content */}
        <div className="space-y-6">
          {/* Step 1: Welcome */}
          {step === 'welcome' && (
            <Card>
