/**
 * DSH Settings Importer
 * Parses YAML settings file from DeepSeek Harness and converts to JiMesh provider configurations
 */
import * as fs from 'fs';
import * as path from 'path';
import * as yaml from 'yaml';
import { getDb } from '../db/index.js';
import { encrypt } from '../lib/crypto.js';
/**
 * Parse DSH YAML settings file
 */
export function parseDSHSettings(filePath) {
    try {
        const content = fs.readFileSync(filePath, 'utf-8');
        const parsed = yaml.parse(content);
        return parsed;
    }
    catch (error) {
        throw new Error(`Failed to parse DSH settings: ${error.message}`);
    }
}
/**
 * Validate provider configuration
 */
export function validateProviderConfig(config, name) {
    const errors = [];
    if (!config.apiKeyEnv) {
        errors.push(`Provider ${name}: missing apiKeyEnv`);
    }

